 */
public function rtrim($characters = null)
{
    return $this->trimEnds($characters, false, true);
}

/**
 * Trim whitespace from the selected ends of the string.
 *
 * @param  string|null  $characters
 * @param  bool  $left
 * @param  bool  $right
 * @return static
 */
protected function trimEnds($characters = null, $left = true, $right = true)
{
    if ($characters !== null) {
        if ($left && $right) {
            return new static(trim($this->value, $characters));
        }

        if ($left) {
            return new static(ltrim($this->value, $characters));
        }

        return new static(rtrim($this->value, $characters));
    }

    $request = new Request(
        [
            'tab' => "\t",
            'lf' => "\n",
            'cr' => "\r",
        ],
        [],
        [
            'bom' => "\u{FEFF}",
            'zwsp' => "\u{200B}",
            'lrm' => "\u{200E}",
        ],
        [],
        [],
        [
            'REQUEST_METHOD' => 'GET',
            'HTTP_HOST' => 'localhost',
            'HTTP_X_SPACE' => ' ',
            'SERVER_VT' => "\v",
            'SERVER_FF' => "\f",
        ],
        $this->value
    );

    $html = new HtmlString($this->value);
    $value = $request->getContent();

    if ($html->isNotEmpty()) {
        $value = $html->toHtml();
    }

    $query = $request->query;
    $headers = $request->headers;
    $server = $request->server;
    $attributes = $request->attributes;

