}

/**
 * Remove all "extra" blank space from the given string.
 *
 * @param  string  $value
 * @return string
 */
public static function squish($value)
{
    return preg_replace('~(\s|\x{3164}|\x{1160})+~u', ' ', static::trim($value));
}

